// Transitional generator: lifts pdf.js's data tables out of the pdfjs-dist
// build the TypeScript engine runs on, so sp-pdf answers from the very same
// tables. Writes src/tables.rs. Deleted at cutover; the generated file stays.
//
//   bun rust/crates/sp-pdf/oracle/gen-tables.ts
//
// Run from the repo root. Each table is evaluated by pdf.js's own code (the
// source text of its declaration, run under a stub of the one helper it
// needs), so iteration order is JavaScript's: integer-like keys first, in
// ascending order, then the rest in insertion order. Some pdf.js lookups walk
// these maps in that order, so the order is kept.
//
// It also measures, with the runtime's own regex engine and normalizer, the
// three Unicode facts pdf.js asks the engine for: which code points `\s`,
// `\p{Mn}` and `\p{Cf}` match, and what NFKC makes of each code point
// normalizeUnicode hands to it.
import { readFileSync, writeFileSync } from 'node:fs';

const src = readFileSync('node_modules/pdfjs-dist/build/pdf.worker.mjs', 'utf8');
const version = JSON.parse(readFileSync('node_modules/pdfjs-dist/package.json', 'utf8')).version;

function declaration(name: string): string {
  const starts = [`const ${name} = `, `function ${name}(`];
  let at = -1;
  for (const s of starts) {
    const i = src.indexOf(`\n${s}`);
    if (i >= 0) {
      at = i + 1;
      break;
    }
  }
  if (at < 0) throw new Error(`no declaration for ${name}`);
  // A declaration ends at the first line that starts at column 0 with `}`
  // or that is itself a complete one-liner ending in `;`.
  const firstLineEnd = src.indexOf('\n', at);
  const firstLine = src.slice(at, firstLineEnd);
  if (firstLine.endsWith(';') && !firstLine.endsWith('{')) return firstLine;
  const end = src.indexOf('\n}', at);
  const close = src.indexOf('\n', end + 1);
  return src.slice(at, close);
}

function getLookupTableFactory(initializer: ((t: Record<string, unknown>) => void) | null, useArray = false) {
  let lookup: unknown;
  return function () {
    if (initializer) {
      lookup = useArray ? [] : Object.create(null);
      initializer(lookup as Record<string, unknown>);
      initializer = null;
    }
    return lookup;
  };
}

function evalDecl(name: string, ...deps: string[]): unknown {
  const code = [...deps, name].map(declaration).join('\n');
  const fn = new Function('getLookupTableFactory', `${code}\nreturn ${name};`);
  return fn(getLookupTableFactory);
}

const rs: string[] = [];
rs.push(`// GENERATED by rust/crates/sp-pdf/oracle/gen-tables.ts from pdfjs-dist ${version}.`);
rs.push('// Do not edit by hand.');
rs.push('//');
rs.push('// The data below is pdf.js\'s (Mozilla Foundation, Apache License 2.0;');
rs.push('// see the notice in this crate\'s NOTICE file). Glyph names, encodings and');
rs.push('// metrics descend from Adobe\'s published glyph list and AFM files.');
rs.push('#![allow(clippy::all)]');
rs.push('');

const q = (s: string) => JSON.stringify(s);

function emitStrArray(rsName: string, arr: string[]) {
  rs.push(`pub static ${rsName}: [&str; ${arr.length}] = [${arr.map(q).join(', ')}];`);
}

function emitStrNumMap(rsName: string, obj: Record<string, number>) {
  const keys = Object.keys(obj);
  rs.push(`pub static ${rsName}: [(&str, u32); ${keys.length}] = [`);
  for (const k of keys) rs.push(`    (${q(k)}, ${obj[k]}),`);
  rs.push('];');
}

function emitNumNumMap(rsName: string, obj: Record<string, number>) {
  const keys = Object.keys(obj);
  rs.push(`pub static ${rsName}: [(u32, u32); ${keys.length}] = [`);
  for (const k of keys) rs.push(`    (${k}, ${obj[k]}),`);
  rs.push('];');
}

function emitNumStrMap(rsName: string, obj: Record<string, string>) {
  const keys = Object.keys(obj);
  rs.push(`pub static ${rsName}: [(u32, &str); ${keys.length}] = [`);
  for (const k of keys) rs.push(`    (${k}, ${q(obj[k])}),`);
  rs.push('];');
}

function emitStrStrMap(rsName: string, obj: Record<string, string>) {
  const keys = Object.keys(obj);
  rs.push(`pub static ${rsName}: [(&str, &str); ${keys.length}] = [`);
  for (const k of keys) rs.push(`    (${q(k)}, ${q(obj[k])}),`);
  rs.push('];');
}

function emitStrSet(rsName: string, obj: Record<string, unknown>) {
  const keys = Object.keys(obj);
  rs.push(`pub static ${rsName}: [&str; ${keys.length}] = [${keys.map(q).join(', ')}];`);
}

// Encodings: 256 glyph names each.
for (const enc of [
  'ExpertEncoding',
  'MacExpertEncoding',
  'MacRomanEncoding',
  'StandardEncoding',
  'WinAnsiEncoding',
  'SymbolSetEncoding',
  'ZapfDingbatsEncoding',
]) {
  const arr = evalDecl(enc) as string[];
  const snake = enc.replace(/([a-z])([A-Z])/g, '$1_$2').toUpperCase();
  emitStrArray(snake, arr);
}

emitStrArray('BIDI_BASE_TYPES', evalDecl('baseTypes') as string[]);
emitStrArray('BIDI_ARABIC_TYPES', evalDecl('arabicTypes') as string[]);
emitStrNumMap('GLYPHS_UNICODE', (evalDecl('getGlyphsUnicode') as () => Record<string, number>)());
emitStrNumMap('DINGBATS_GLYPHS_UNICODE', (evalDecl('getDingbatsGlyphsUnicode') as () => Record<string, number>)());
emitNumNumMap('SPECIAL_PUA_SYMBOLS', (evalDecl('getSpecialPUASymbols') as () => Record<string, number>)());
emitNumNumMap('VERTICAL_PRESENTATION_FORM', (evalDecl('getVerticalPresentationForm') as () => Record<string, number>)());
emitStrStrMap('STD_FONT_MAP', (evalDecl('getStdFontMap') as () => Record<string, string>)());
emitStrStrMap('NON_STD_FONT_MAP', (evalDecl('getNonStdFontMap') as () => Record<string, string>)());
emitStrSet('SERIF_FONTS', (evalDecl('getSerifFonts') as () => Record<string, unknown>)());
emitStrSet('SYMBOLS_FONTS', (evalDecl('getSymbolsFonts') as () => Record<string, unknown>)());
emitNumNumMap('GLYPH_MAP_FOR_MAC_ORDERED_FONTS', (evalDecl('getGlyphMapForMacOrderedFonts', 'getGlyphsUnicode', 'MacStandardGlyphOrdering') as () => Record<string, number>)());
emitNumNumMap('GLYPH_MAP_FOR_STANDARD_FONTS', (evalDecl('getGlyphMapForStandardFonts') as () => Record<string, number>)());
emitNumNumMap(
  'SUPPLEMENTAL_GLYPH_MAP_FOR_TREBUCHET_MS',
  (evalDecl('getSupplementalGlyphMapForTrebuchetMS') as () => Record<string, number>)(),
);
emitNumNumMap(
  'SUPPLEMENTAL_GLYPH_MAP_FOR_ARIAL_BLACK',
  (evalDecl('getSupplementalGlyphMapForArialBlack') as () => Record<string, number>)(),
);
emitNumNumMap(
  'SUPPLEMENTAL_GLYPH_MAP_FOR_CALIBRI',
  (evalDecl('getSupplementalGlyphMapForCalibri') as () => Record<string, number>)(),
);
emitNumStrMap('SYMBOL_GLYPH_ID_ENCODING', (evalDecl('getSymbolGlyphIdEncoding', 'SymbolSetEncoding') as () => Record<string, string>)());

// Metrics: a font is either one width for every glyph (the Courier family)
// or a glyph-name table.
{
  const metrics = (evalDecl('getMetrics') as () => Record<string, number | (() => Record<string, number>)>)();
  const names = Object.keys(metrics);
  const tables: string[] = [];
  rs.push('pub enum StdMetrics {');
  rs.push('    Fixed(f64),');
  rs.push("    Table(&'static [(&'static str, f64)]),");
  rs.push('}');
  rs.push(`pub static METRICS: [(&str, StdMetrics); ${names.length}] = [`);
  for (const [i, n] of names.entries()) {
    const m = metrics[n];
    if (typeof m === 'number') {
      rs.push(`    (${q(n)}, StdMetrics::Fixed(${m}.0)),`);
    } else {
      const t = m();
      const ks = Object.keys(t);
      tables.push(
        `static METRICS_${i}: [(&str, f64); ${ks.length}] = [${ks.map((k) => `(${q(k)}, ${Number.isInteger(t[k]) ? `${t[k]}.0` : t[k]})`).join(', ')}];`,
      );
      rs.push(`    (${q(n)}, StdMetrics::Table(&METRICS_${i})),`);
    }
  }
  rs.push('];');
  rs.push(...tables);
}

// Unicode facts, measured on the runtime pdf.js runs under.
function ranges(test: (s: string) => boolean): [number, number][] {
  const out: [number, number][] = [];
  let start = -1;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const hit = !(cp >= 0xd800 && cp <= 0xdfff) && test(String.fromCodePoint(cp));
    if (hit && start < 0) start = cp;
    if (!hit && start >= 0) {
      out.push([start, cp - 1]);
      start = -1;
    }
  }
  if (start >= 0) out.push([start, 0x10ffff]);
  return out;
}
function emitRanges(rsName: string, r: [number, number][]) {
  rs.push(`pub static ${rsName}: [(u32, u32); ${r.length}] = [${r.map(([a, b]) => `(${a}, ${b})`).join(', ')}];`);
}
emitRanges('JS_WHITESPACE', ranges((s) => /^\s$/u.test(s)));
emitRanges('UNICODE_MN', ranges((s) => /^\p{Mn}$/u.test(s)));
emitRanges('UNICODE_CF', ranges((s) => /^\p{Cf}$/u.test(s)));

// normalizeUnicode: the code points its regex sends to NFKC, and what NFKC
// makes of each one alone.
{
  const decl = declaration('normalizeUnicode');
  const m = decl.match(/NormalizeRegex = \/(\(\[.*?\]\+\))\|\(\\ufb05\+\)\/gu;/);
  if (!m) throw new Error('normalizeUnicode regex not found');
  const cls = new RegExp(`^${m[1].slice(1, -2)}$`, 'u');
  const nfkc: [number, string][] = [];
  for (let cp = 0; cp <= 0xffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    const s = String.fromCodePoint(cp);
    if (cls.test(s)) nfkc.push([cp, s.normalize('NFKC')]);
  }
  rs.push(`pub static NFKC_MAP: [(u32, &str); ${nfkc.length}] = [`);
  for (const [cp, s] of nfkc) rs.push(`    (${cp}, ${q(s)}),`);
  rs.push('];');
}

writeFileSync('rust/crates/sp-pdf/src/tables.rs', `${rs.join('\n')}\n`);
console.log('wrote rust/crates/sp-pdf/src/tables.rs');
